# Same funded accounts, with distinct account exit and legal claim settlement.
if(!exists('build_recovery_episodes'))library(creditratingsystem)
rap_helper<-'creditratingsystem-r/examples/retail_application_journey.R';if(!file.exists(rap_helper))rap_helper<-system.file('examples','retail_application_journey.R',package='creditratingsystem');source(rap_helper)
rap_assess<-function(case,ledger,cutoff,bindings){
 x<-ledger;aid<-x$account_id;key<-x$application_id;booking<-Filter(function(b)b$application_id==key,case$bookings)[[1]];default<-Filter(function(d)d$facility_id==aid,case$defaults)[[1]];exit<-Filter(function(e)e$facility_id==aid,case$exits)[[1]];econ<-Filter(function(e)e$application_id==key,case$realized_economics)[[1]];lease<-case$terms$kind=='OPERATING_RENT'
 if(x$settlement_known_at>cutoff||x$settlement_date<x$claim_cash_date||x$settlement_known_at<x$settlement_date||x$account_exit_date!=exit$exit_at)stop('Separate dated account exit and legal settlement required')
 if(x$claim_cash+x$claim_waiver!=x$claim_amount||x$investment_recovery!=econ$principal_cash||x$investment_cost!=econ$principal_funded)stop('Claim settlement and investment cash must reconcile separately')
 if(lease&&(x$scope!='UNPAID_RENT_CLAIM'||x$claim_amount!=case$terms$rent||x$claim_cash!=0||case$terms$customer_residual_liability!=0))stop('Asset disposal is not tenant rent or residual liability')
 if(!lease&&(x$scope!='PRINCIPAL_CLAIM'||x$claim_amount!=x$investment_cost||x$claim_cash!=x$investment_recovery))stop('Principal claim must match original funded principal')
 if(x$proposal_status!='SCENARIO_NOT_ACCEPTED'||x$proposal_date>x$proposal_known_at||x$proposal_known_at>=default$default_at)stop('Only dated predefault unaccepted proposal supplied')
 due<-as.character(as.Date(booking$first_draw_at)+10);amount<-rj_payment(case$terms)[[1]];obligations<-list(list(obligation_id=paste0(aid,'-due'),account_id=aid,due_at=due,known_at=booking$first_draw_known_at,amount=amount,currency='EUR'));dpd<-compute_days_past_due(obligations,list(),as_of=x$proposal_date,known_at=x$proposal_known_at,currency='EUR')$value
 baseline<-list(plan_id='claim-no-new-agreement',payments=list(0,0,0),period_interest_rates=list(0,0,0),new_fees=list(0,0,0),servicing_costs=list(0,0,0),receipt_fractions=list(1,1,1),capitalize_unpaid_interest=FALSE);candidate<-baseline;candidate$plan_id<-'proposed-only';candidate$payments<-x$proposal_payments;for(k in c('payments','period_interest_rates','new_fees','servicing_costs','receipt_fractions')){baseline[[k]]<-unlist(baseline[[k]]);candidate[[k]]<-unlist(candidate[[k]])}
 proposal<-simulate_repayment_arrangement(list(currency='EUR',principal=x$claim_amount,principal_arrears=min(dpd$past_due_amount,x$claim_amount),accrued_interest=0,fees=0,as_of=x$proposal_date),baseline,candidate,affordability_paths=list(list(path_id='declared-capacity',currency='EUR',available_cash=unlist(x$proposal_available_cash))),discount_factors=c(1,1,1),period_end_dates=unlist(x$proposal_dates),currency='EUR')$value
 ep<-paste0(aid,'-legal-workout');cf<-list(list(cashflow_id=paste0(ep,'-cash'),episode_id=ep,cashflow_at=x$claim_cash_date,known_at=x$settlement_known_at,amount=x$claim_cash,kind='recovery',currency='EUR'));defaults<-list(list(episode_id=ep,entity_id=aid,default_at=default$default_at,known_at=default$known_at,ead=x$claim_amount,currency='EUR'));closures<-list(list(closure_id=paste0(ep,'-terminal'),episode_id=ep,closed_at=x$settlement_date,known_at=x$settlement_known_at,closure_reason='SETTLEMENT'))
 linked<-build_recovery_episodes(defaults,cf,cures=list(),closures=closures,evaluation_cutoff=cutoff)$value;early<-build_recovery_episodes(defaults,cf,cures=list(),closures=closures,evaluation_cutoff=exit$known_at)$value
 cash<-list(list(cashflow_id=cf[[1]]$cashflow_id,cashflow_date=x$claim_cash_date,known_at=x$settlement_known_at,amount=x$claim_cash,kind='RECOVERY',currency='EUR'));discounted<-discount_recoveries(cash,list(anchor_date=default$default_at,known_at=default$known_at,discount_basis='DECLARED_ZERO_RATE_CLAIM',points=list(list(cashflow_date=x$claim_cash_date,discount_factor=1))),list(reporting_currency='EUR',known_at=default$known_at,conversion_basis='cashflow_date',rates=list(list(currency='EUR',date=x$claim_cash_date,rate=1))),default_date=default$default_at,evaluation_cutoff=cutoff,reporting_currency='EUR');loss<-workout_lgd(x$claim_amount,discounted,episode_status='CLOSED',default_date=default$default_at,evaluation_cutoff=cutoff,currency='EUR')$value
 distribution<-credit_loss_distribution(vapply(case$realized_economics,function(e)e$principal_funded-e$principal_cash,0.),rep(1,length(case$realized_economics)),scenario_ids=vapply(case$realized_economics,function(e)e$facility_id,''),levels=.95,currency='EUR')$value
 payloads<-list(list('ORIGINATION',booking$first_draw_at,booking$first_draw_known_at,list(funded=TRUE)),list('PERFORMING',booking$first_draw_at,booking$first_draw_known_at,list(account_active=TRUE)),list('REVIEW_EARLY_WARNING',x$proposal_date,x$proposal_known_at,list(dpd=dpd$dpd)),list('DELINQUENCY',x$proposal_date,x$proposal_known_at,list(past_due=dpd$past_due_amount,in_arrears=dpd$dpd>0)),list('RESTRUCTURING',x$proposal_date,x$proposal_known_at,list(proposal_only=TRUE,contract_changed=FALSE)),list('DEFAULT_WORKOUT',default$default_at,default$known_at,list(ever_default=TRUE,legal_claim=x$claim_amount)),list('EXIT',exit$exit_at,exit$known_at,list(account_closed=TRUE,legal_claim_remaining=x$claim_amount)),list('LEGAL_SETTLEMENT',x$settlement_date,x$settlement_known_at,list(legal_claim_remaining=0,waived=x$claim_waiver,ever_default=TRUE)),list('PORTFOLIO_MONITORING',x$settlement_date,x$settlement_known_at,list(realized_investment_loss=x$investment_cost-x$investment_recovery)))
 events<-lapply(seq_along(payloads),function(i){p<-payloads[[i]];id<-paste0(aid,'-',p[[1]]);list(event_id=id,idempotency_key=id,occurred_at=p[[2]],known_at=p[[3]],sequence=i-1L,payload=p[[4]],revision_of=NULL,payload_hash=content_fingerprint(p[[4]])$value)});events<-c(events,list(events[[5]]));deps<-list(list(assessment_id=paste0(aid,'-assessment'),dependency_type='account',dependency_id=aid))
 execute<-function(){state<-NULL;account_state<-list();seen<-ids<-character();ordered<-events[order(vapply(events,function(e)e$known_at,''),vapply(events,function(e)e$sequence,0),vapply(events,function(e)e$event_id,''))];for(e in ordered){if(e$idempotency_key%in%seen)next;seen<-c(seen,e$idempotency_key);ids<-c(ids,e$event_id);for(k in names(e$payload))account_state[[k]]<-e$payload[[k]];state<-apply_assessment_event(state,list(event_id=e$event_id,revision='1',occurred_at=e$occurred_at,known_at=e$known_at,dependencies=list(list(type='account',id=aid)),payload=e$payload),deps,cutoff)$value$state};list(ids=as.list(ids),state=list(dependencies=state,account=account_state))}
 first<-execute();second<-execute();snaps<-lapply(c(MODEL='model',CALIBRATION='calibrator',POLICY='policy'),function(field)list(kind=names(c(MODEL='model',CALIBRATION='calibrator',POLICY='policy'))[match(field,c('model','calibrator','policy'))],content_hash=bindings[[field]],known_at='2024-01-01',effective_from='2024-01-01',effective_until=NULL));for(i in seq_along(snaps))snaps[[i]]$snapshot_id<-snaps[[i]]$kind;snaps<-c(unname(snaps),list(list(snapshot_id='SOURCE',kind='SOURCE',content_hash=content_fingerprint(list(case=case,ledger=x,bindings=bindings))$value,known_at=cutoff,effective_from=cutoff,effective_until=NULL)));base<-list(checkpoint_id=paste0(aid,'-final'),as_of=cutoff,known_at=cutoff,event_log_hash=content_fingerprint(events)$value,snapshot_hashes=setNames(lapply(snaps,function(r)r$content_hash),vapply(snaps,function(r)r$snapshot_id,'')))
 replay_inputs<-list(event_log=events,original_checkpoints=list(c(base,list(applied_event_ids=first$ids,state=first$state))),replayed_checkpoints=list(c(base,list(applied_event_ids=second$ids,state=second$state,mode='REPLAY'))),snapshot_manifest=snaps,replay_contract=list(contract_id=paste0(aid,'-allphase'),version='1',reference='Two actual public reducer executions; account exit and legal settlement separate',ordering='KNOWN_AT_SEQUENCE_EVENT_ID',idempotency='FIRST_IDENTICAL_DELIVERY',corrections='APPEND_REVISION',required_checkpoint_ids=list(base$checkpoint_id),absolute_tolerance=1e-12,relative_tolerance=0));replay<-do.call(replay_consistency,replay_inputs)$value
 stopifnot(replay$decision$status=='PASS',!proposal$contract_changed,loss$economic_loss==x$claim_waiver)
 summary<-list(account_id=aid,application_id=key,product_contract=case$terms,claim_scope=x$scope,dpd=dpd$dpd,past_due=dpd$past_due_amount,proposal_only=TRUE,baseline_scope='NO_NEW_RECEIPT_SCENARIO_NOT_REPLACEMENT_CONTRACT_SCHEDULE',account_exit=exit$exit_at,legal_settlement=x$settlement_date,legal_claim_at_account_exit=x$claim_amount,claim_cash=x$claim_cash,claim_waiver=x$claim_waiver,remaining_claim=0,ever_default=TRUE,investment_loss=x$investment_cost-x$investment_recovery,loss_scopes_not_added=lease,realized_book_mean_loss=distribution$expected_loss,replay_status=replay$decision$status,phases=lapply(Filter(function(p)p[[1]]!='LEGAL_SETTLEMENT',payloads),function(p)p[[1]]))
 list(summary=summary,proposal=proposal,workout=loss,recovery_episodes=linked,episodes_at_account_exit=early,replay_inputs=replay_inputs,replay=replay,distribution=distribution)
}
run_retail_application_phases<-function(data=NULL,application_data=NULL,application_chain=NULL,product_ids=NULL,return_artifacts=FALSE){
 if(is.null(data))data<-jsonlite::read_json(rj_resource('retail_application_phases.json'),simplifyVector=FALSE);if(is.null(application_data))application_data<-jsonlite::read_json(rj_resource('retail_application_journey.json'),simplifyVector=FALSE);chosen<-if(is.null(product_ids))names(data$products)else product_ids;if(is.null(application_chain))application_chain<-run_retail_application_journey(application_data,product_ids=chosen,return_artifacts=TRUE);out<-list()
 for(p in chosen){origin<-application_chain$products[[p]];binding<-lapply(list(model=origin$fitted$model,calibrator=origin$fitted$calibrator,policy=origin$policy),function(v)content_fingerprint(v)$value);out[[p]]<-rap_assess(application_data$products[[p]],data$products[[p]],data$evaluation_cutoff,binding)}
 result<-list(journey_id='J_SYSTEM_EVENT_REPLAY',data_origin='SYNTHETIC',products=lapply(out,function(x)x$summary),scope='Same original funded accounts, product-specific claims; no new fitted model and no causal proposal benefit or portfolio forecast');if(return_artifacts)result$raw_artifacts<-out;result
}
